<script>
(function () {
  'use strict';

  var form = document.getElementById('signup');
  var status = document.getElementById('status');
  var toggle = document.getElementById('toggle-password');
  var passwordInput = document.getElementById('password');
  var fields = Array.prototype.slice.call(form.querySelectorAll('input'));

  var PASSWORD_MIN = 8;
  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  var SCHEME_RE = /^[a-z][a-z0-9+.\-]*:\/\//i;
  var HOSTNAME_RE = /^(?:[a-z0-9](?:[a-z0-9\-]*[a-z0-9])?\.)+[a-z][a-z0-9\-]*[a-z0-9]$/i;

  // Messages affichés lorsqu'un champ obligatoire est laissé vide.
  var requiredMessages = {
    fullname: 'Veuillez indiquer votre nom complet.',
    email: 'Veuillez indiquer votre adresse e-mail.',
    website: 'Veuillez indiquer l’adresse de votre site web.',
    password: 'Veuillez choisir un mot de passe.'
  };

  // Nettoyage de la valeur avant contrôle (le mot de passe n'est jamais modifié).
  var cleaners = {
    fullname: function (v) { return v.trim().replace(/\s+/g, ' '); },
    email: function (v) { return v.trim(); },
    website: function (v) {
      v = v.trim();
      // « exemple.fr » est accepté et complété en « https://exemple.fr ».
      if (v && !SCHEME_RE.test(v)) { v = 'https://' + v; }
      return v;
    },
    password: function (v) { return v; }
  };

  // Chaque fonction reçoit une valeur non vide et renvoie un message d'erreur,
  // ou une chaîne vide si la valeur est correcte.
  var validators = {
    fullname: function (v) {
      if (v.length < 2) { return 'Le nom doit comporter au moins 2 caractères.'; }
      if (v.length > 100) { return 'Le nom ne peut pas dépasser 100 caractères.'; }
      return '';
    },

    email: function (v) {
      if (v.length > 254 || !EMAIL_RE.test(v)) {
        return 'Adresse e-mail invalide (exemple : prenom.nom@exemple.fr).';
      }
      return '';
    },

    website: function (v) {
      var invalid = 'Adresse de site invalide (exemple : https://exemple.fr).';
      var url;
      if (/\s/.test(v)) { return invalid; }
      try {
        url = new URL(v);
      } catch (e) {
        return invalid;
      }
      if (url.protocol !== 'http:' && url.protocol !== 'https:') {
        return 'L’adresse doit commencer par http:// ou https://.';
      }
      if (url.username || url.password || !HOSTNAME_RE.test(url.hostname)) {
        return invalid;
      }
      return '';
    },

    password: function (v) {
      if (v.length < PASSWORD_MIN) {
        return 'Le mot de passe doit comporter au moins ' + PASSWORD_MIN + ' caractères.';
      }
      return '';
    }
  };

  function showError(input, message) {
    var error = document.getElementById(input.id + '-error');
    error.textContent = message; // textContent : jamais d'injection de HTML
    error.hidden = !message;
    if (message) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
  }

  // Valide un champ et affiche ou efface son message d'erreur.
  // Si « commit » est vrai, la valeur nettoyée est réécrite dans le champ.
  function validateField(input, commit) {
    var name = input.name;
    var value = cleaners[name](input.value);
    var isEmpty = name === 'password' ? value.trim() === '' : value === '';
    var message = '';

    if (isEmpty) {
      message = input.required ? requiredMessages[name] : '';
    } else {
      message = validators[name](value);
    }

    if (commit && name !== 'password' && input.value !== value) {
      input.value = value;
    }

    showError(input, message);
    return !message;
  }

  fields.forEach(function (input) {
    // À la sortie du champ : contrôle s'il a été rempli ou déjà signalé en erreur.
    input.addEventListener('blur', function () {
      if (input.value !== '' || input.getAttribute('aria-invalid') === 'true') {
        validateField(input, true);
      }
    });

    // Pendant la saisie : l'erreur disparaît dès que la valeur devient correcte.
    input.addEventListener('input', function () {
      status.textContent = '';
      if (input.getAttribute('aria-invalid') === 'true') {
        validateField(input, false);
      }
    });
  });

  function setPasswordVisible(visible) {
    passwordInput.type = visible ? 'text' : 'password';
    toggle.textContent = visible ? 'Masquer' : 'Afficher';
    toggle.setAttribute('aria-label',
      (visible ? 'Masquer' : 'Afficher') + ' le mot de passe');
  }

  toggle.addEventListener('click', function () {
    setPasswordVisible(passwordInput.type === 'password');
  });

  form.addEventListener('submit', function (event) {
    var firstInvalid = null;

    status.textContent = '';
    setPasswordVisible(false);

    fields.forEach(function (input) {
      if (!validateField(input, true) && !firstInvalid) {
        firstInvalid = input;
      }
    });

    if (firstInvalid) {
      event.preventDefault();
      firstInvalid.focus();
      return;
    }

    // Formulaire valide. Si un attribut « action » est défini, l'envoi natif
    // se poursuit normalement. Sinon (page de démonstration), on confirme.
    if (!form.hasAttribute('action')) {
      event.preventDefault();
      form.reset();
      status.textContent = 'Inscription validée. Merci !';
    }
  });
})();
</script>
